one-out-two-types:
MATCH (a:`Hub`) WHERE a.`hubId` IN [$stableId, $stableInteger] WITH a ORDER BY elementId(a) LIMIT 1
CALL { WITH a CALL { WITH a MATCH (a)-[r:`A`]->(n:`Hub`) WHERE n <> a RETURN n, r, true AS isTarget UNION ALL WITH a MATCH (a)-[r:`B`]->(n:`Hub`) WHERE n <> a RETURN n, r, true AS isTarget } WITH n, r, isTarget LIMIT $countCap + 1 WITH collect({n: n, r: r, isTarget: isTarget}) AS found RETURN size(found) > $countCap AS cutFirst, found[..$countCap] AS nbs }
WITH a, nbs, cutFirst, [] AS heavy, false AS stopListed, false AS cutSecond, [] AS second
WITH a, cutFirst OR cutSecond AS bounded, heavy, stopListed, [e IN nbs WHERE e.isTarget | {x: e.n, hops: 1, m: null, r1: e.r, r2: null}] + [h IN second | {x: h.x, hops: 2, m: h.m, r1: [e IN nbs WHERE e.n = h.m][0].r, r2: h.r2}] AS entries
CALL { WITH entries UNWIND entries AS entry WITH entry ORDER BY entry.hops WITH entry.x AS x, collect(entry)[0] AS best ORDER BY best.hops, x.`hubId` LIMIT $limit + 1 RETURN collect(best) AS ms }
UNWIND CASE WHEN size(ms) = 0 THEN [null] ELSE ms END AS m
CALL { WITH m WITH m, startNode(m.r1) AS s, endNode(m.r1) AS e OPTIONAL MATCH (s)-[rr:`B`]->(e) WHERE type(rr) = type(m.r1) WITH rr LIMIT $countCap + 1 RETURN collect(rr) AS members1 }
RETURN a, bounded, heavy[..$limit] AS heavy, stopListed, m.x AS x, m.m AS mid, m.r1 AS r1, m.r2 AS r2, m.hops AS hops, members1, size(members1) > $countCap AS membersCut

