MATCH (a:`Hub`) WHERE a.`hubId` IN [$stableId, $stableInteger] WITH a ORDER BY elementId(a) LIMIT 1
CALL { WITH a CALL { WITH a MATCH (a)-[r:`A`]->(n:`Hub`) WHERE n <> a AND CASE WHEN r.`seenAt` IS :: ZONED DATETIME THEN r.`seenAt` WHEN r.`seenAt` IS :: LOCAL DATETIME THEN datetime({datetime: r.`seenAt`, timezone: 'UTC'}) WHEN r.`seenAt` IS :: DATE THEN datetime({date: r.`seenAt`, timezone: 'UTC'}) END >= datetime($windowFrom) AND CASE WHEN r.`seenAt` IS :: ZONED DATETIME THEN r.`seenAt` WHEN r.`seenAt` IS :: LOCAL DATETIME THEN datetime({datetime: r.`seenAt`, timezone: 'UTC'}) WHEN r.`seenAt` IS :: DATE THEN datetime({date: r.`seenAt`, timezone: 'UTC'}) END < datetime($windowTo) RETURN n, r, true AS isTarget } WITH n, r, isTarget LIMIT $countCap + 1 WITH collect({n: n, r: r, isTarget: isTarget}) AS found RETURN size(found) > $countCap AS cutFirst, found[..$countCap] AS nbs }
CALL { WITH nbs UNWIND nbs AS e WITH DISTINCT e.n AS n WHERE n:`Hub` CALL { WITH n MATCH (n)-[:`A`]->() WITH 1 AS hit LIMIT $countCap + 1 RETURN count(*) AS c0 } WITH n, c0 AS degree, false AS stopped RETURN collect(CASE WHEN degree > $countCap THEN n END) AS heavy, collect(CASE WHEN degree <= $countCap AND NOT stopped THEN n END) AS mids, count(CASE WHEN stopped THEN 1 END) > 0 AS stopListed }
