two-stop-list-and-aggregate:
MATCH (a:`Hub`) WHERE a.`hubId` IN [$stableId, $stableInteger] WITH a ORDER BY elementId(a) LIMIT 1
CALL { WITH a CALL { WITH a MATCH (a)-[r:`B`]->(n:`Hub`) WHERE n <> a RETURN n, r, true AS isTarget UNION ALL WITH a MATCH (a)-[r:`C`]->(n:`Leaf`) WHERE n <> a RETURN n, r, false AS isTarget } WITH n, r, isTarget LIMIT $countCap + 1 WITH collect({n: n, r: r, isTarget: isTarget}) AS found RETURN size(found) > $countCap AS cutFirst, found[..$countCap] AS nbs }
CALL { WITH nbs UNWIND nbs AS e WITH DISTINCT e.n AS n WHERE n:`Hub` OR n:`Leaf` CALL { WITH n MATCH (n)-[:`C`]->() WITH 1 AS hit LIMIT $countCap + 1 RETURN count(*) AS c0 } CALL { WITH n MATCH (n)-[:`D`]->() WITH 1 AS hit LIMIT $countCap + 1 RETURN count(*) AS c1 } CALL { WITH n MATCH (n)-[:`B`]->() WITH 1 AS hit LIMIT $countCap + 1 RETURN count(*) AS c2 } WITH n, c0 + c1 + c2 AS degree, (n:`Leaf` AND coalesce(n.`isHot`, false) = true) AS stopped RETURN collect(CASE WHEN degree > $countCap THEN n END) AS heavy, collect(CASE WHEN degree <= $countCap AND NOT stopped THEN n END) AS mids, count(CASE WHEN stopped THEN 1 END) > 0 AS stopListed }
CALL { WITH a, mids UNWIND mids AS n CALL { WITH a, n MATCH (n:`Hub`)-[r2:`B`]->(x:`Hub`) WHERE x <> a RETURN x, r2 UNION ALL WITH a, n MATCH (n:`Leaf`)-[r2:`D`]->(x:`Hub`) WHERE x <> a RETURN x, r2 } WITH n, x, r2 LIMIT $countCap + 1 WITH collect({x: x, m: n, r2: r2}) AS found RETURN size(found) > $countCap AS cutSecond, found[..$countCap] AS second }
WITH a, cutFirst OR cutSecond AS bounded, heavy, stopListed, [e IN nbs WHERE e.isTarget | {x: e.n, hops: 1, m: null, r1: e.r, r2: null}] + [h IN second | {x: h.x, hops: 2, m: h.m, r1: [e IN nbs WHERE e.n = h.m][0].r, r2: h.r2}] AS entries
CALL { WITH entries UNWIND entries AS entry WITH entry ORDER BY entry.hops WITH entry.x AS x, collect(entry)[0] AS best ORDER BY best.hops, x.`hubId` LIMIT $limit + 1 RETURN collect(best) AS ms }
UNWIND CASE WHEN size(ms) = 0 THEN [null] ELSE ms END AS m
CALL { WITH m WITH m, startNode(m.r1) AS s, endNode(m.r1) AS e OPTIONAL MATCH (s)-[rr:`B`]->(e) WHERE type(rr) = type(m.r1) WITH rr LIMIT $countCap + 1 RETURN collect(rr) AS members1 }
CALL { WITH m WITH m, startNode(m.r2) AS s, endNode(m.r2) AS e OPTIONAL MATCH (s)-[rr:`B`]->(e) WHERE type(rr) = type(m.r2) WITH rr LIMIT $countCap + 1 RETURN collect(rr) AS members2 }
RETURN a, bounded, heavy[..$limit] AS heavy, stopListed, m.x AS x, m.m AS mid, m.r1 AS r1, m.r2 AS r2, m.hops AS hops, members1, members2, size(members1) > $countCap OR size(members2) > $countCap AS membersCut
